1	/**
2	 * max-member-chain — Law of Demeter. A chain like `a.b.c.d` or `a.b().c.d()`
3	 * reaches through collaborators the caller has no business knowing; the
4	 * caller should ask its direct collaborator for what it needs.
5	 *
6	 * Depth = number of `MemberExpression` hops from the chain's root. Computed
7	 * hops (`a[0].b`) and optional hops (`a?.b`) count like any other. Only the
8	 * OUTERMOST member expression of a chain is reported — an inner one whose
9	 * parent continues the chain (as the object of another member, or as the
10	 * callee of a call that is itself continued) is skipped.
11	 *
12	 * Exempt:
13	 *  - the root is `this` / `super`;
14	 *  - the root is a well-known global (`Math`, `JSON`, `Promise`, `Object`,
15	 *    `Array`, `Number`, `String`, `Reflect`, `process`, `console`,
16	 *    `globalThis`, `window`, `document`, `Symbol`, `Date`) or a name listed
17	 *    in option `allowRoots`;
18	 *  - every hop after the root is a call (`builder().a().b().c()` fluent
19	 *    chains return the same kind of thing at each step);
20	 *  - chains rooted in `import.meta`.
21	 *
22	 * Detect-only: the fix is a method on the direct collaborator.
23	 */
24	const DEFAULT_MAX = 2;
25	const CHAIN_TEXT_LIMIT = 60;
26	const DEFAULT_ALLOWED_ROOTS = new Set([
27	    "Math",
28	    "JSON",
29	    "Promise",
30	    "Object",
31	    "Array",
32	    "Number",
33	    "String",
34	    "Reflect",
35	    "process",
36	    "console",
37	    "globalThis",
38	    "window",
39	    "document",
40	    "Symbol",
