      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});

type SchemaErrors = NonNullable<ValidateFunction['errors']>;

function rejectionMessage(toolName: string, errors: SchemaErrors): string {
  const issues = errors
    .map(error => (error.instancePath ? `${error.instancePath} ${error.message}` : error.message))
    .join('; ');
  return `Invalid input for tool "${toolName}": ${issues}`;
}

function compiledValidator(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {cause: error});
  }
}

